        while(b) { if(b&1) s=add(mul({jump00[j],jump01[j]},s),mul(inc,{jump10[j],jump11[j]})); b>>=1;++j; }
        base=s;
    }
    __syncthreads();
    int t=threadIdx.x; long long i=(long long)blockIdx.x*256+t;
    if(i<n) {
        U128 s=add(mul({off00[t],off01[t]},base),mul(inc,{off10[t],off11[t]}));
        unsigned long long v=s.hi^s.lo; unsigned int r=s.hi>>58;
        out[i]=(v>>r)|(v<<((-r)&63));
    }
}
extern "C" __global__ void classify(const unsigned long long* words, double* xout, unsigned char* rare, unsigned char* accept, unsigned char* ambiguous, long long n) {
    long long i=(long long)blockIdx.x*blockDim.x+threadIdx.x;if(i>=n)return;
    unsigned long long ri=words[i]>>3;int idx=ri&255;ri>>=8;
    double x=(double)ri*we_double[idx]; bool unusual=ri>=ke_double[idx];bool ok=true;bool near=false;
    if(unusual) {
        double u=(double)(words[i+1]>>11)*0x1.0p-53;
        if(idx==0) x=7.6971174701310497140446280481-log1p(-u);
        else {
            double lhs=(fe_double[idx-1]-fe_double[idx])*u+fe_double[idx];double rhs=exp(-x);
            ok=lhs<rhs;near=fabs(lhs-rhs)<=128*0x1.0p-52*fmax(fabs(lhs),fabs(rhs));
        }
    }
    xout[i]=x;rare[i]=unusual;accept[i]=ok;ambiguous[i]=near;
}
extern "C" __global__ void validity(const unsigned char* rare,unsigned char* valid,long long n) {
 long long i=(long long)blockIdx.x*blockDim.x+threadIdx.x;if(i>=n)return;
 long long j=i-1;while(j>=0 && rare[j])--j;
 valid[i]=((i-j-1)&1)==0;
}
